WITH payload AS (SELECT $archive_payload$[{"id":"a2c2c27f-5923-52ab-b98d-b7d85ca85c40","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة ابنتها -تقدير نفقة عن طريق قسم اخلبراء -التوكيل أثناء الترافع -احلكم بالنفقة مع شموله بالنفاذ املعجل .","document_number":"3419050","case_number":"33497828","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/21","year":"1434","subject":"نفقة -مطالبة أم بنفقة ابنتها -تقدير نفقة عن طريق قسم اخلبراء -التوكيل أثناء الترافع -احلكم بالنفقة مع شموله بالنفاذ املعجل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/1/21 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪3419050 :‬‬\n                         ‫َر ْق ُم الدعوى‪33497828 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n         ‫‪/34141339‬ش‪/1‬أ تاريخه‪1434/3/24 :‬هـ‬\n\n\n\n      ‫نفقــة ‪ -‬مطالبــة أم بنفقــة ابنتهــا ‪ -‬تقديــر نفقــة عــن طريــق قســم‬\n      ‫اخلبــراء ‪ -‬التوكيــل أثنــاء الترافــع ‪ -‬احلكــم بالنفقــة مــع شــموله‬\n                                                             ‫بالنفــاذ املعجــل ‪.‬‬\n\n\n\n\n                                                  ‫قوله تعالى{ل ُِي ْنفِ ْق ُذو َس َع ٍة مِ ْن َس َع ِتهِ}‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بالوكالــة بــأن موكلتــه كانــت زوجــة للمدعــى عليــه‬\n      ‫وطلقهــا ورزقــت منــه ببنــت واحــدة واملدعــى عليــه ال ينفــق علــى ابنتــه إال‬\n      ‫يف األعيــاد وطالــب املدعــي وكالــة بإلــزام املدعــى عليــه بنفقــة البنــت ‪-‬‬\n      ‫أجــاب املدعــى عليــه باملصادقــة علــى الدعــوى ســوى عــدم اإلنفــاق فقــرر‬\n      ‫أنــه ينفــق علــى البنــت حســب قدرتــه املاديــة ‪ -‬مت تقديــر النفقــة مــن قبــل‬\n      ‫قســم اخلبــراء باحملكمــة مبلغ ـ ًا قــدره أربعمائــة ريــال شــهري ًا ‪ -‬لقولــه‬\n      ‫تعالى{ل ُِي ْنفِ ـ ْـق ُذو َسـ َـع ٍة مِ ــنْ َسـ َـع ِت ِه } فقــد صــدر احلكــم مشــمو ًال بالنفــاذ‬\n      ‫املعجــل بتســليم املدعيــة نفقــة شــهرية البنتهمــا قدرهــا أربعمائــة ريــال‬\n           ‫شــهريا وصــدر قــرار محكمــة االســتئناف باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n‫‪181‬‬\n\f‫احلمــد هلل وحــده والصــاة علــى مــن ال نبــي بعــده ‪ ،‬أمــا بعــد فلــدي أنــا‬\n‫القاضــي يف احملكمــة العامــة مبحافظــة القطيــف ‪ ،‬وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيس احملكمة العامــة مبحافظة القطيف برقم‬\n‫‪ 33497828‬يف ‪1433/7/30‬هـ املقيدة يف احملكمة برقم ‪331442723‬‬\n‫يف ‪1433/7/30‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/10/28‬ه ـ الســاعة‬\n‫التاســعة صباح ـ ًا افتتحــت اجللســة وفيهــا ‪........‬حضــر ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ........‬بصفتــه الوكيــل الشــرعي عــن ‪........‬‬\n‫ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ........‬مبوجــب صــك‬\n‫الوكالــة الصــادر مــن كتابــة عــدل محافظــة القطيــف برقــم ‪........‬يف‬\n‫‪1432/1/5‬ه ـ وادعــى علــى احلاضــر معــه ‪........‬ســعودي اجلنســية مبوجــب‬\n‫ا يف دعــواه‪ :‬لقــد ســبق أن تــزوج املدعــى‬    ‫الســجل املدنــي رقــم ‪ ........‬قائ ـ ً‬\n‫عليــه موكلتــي أختــي بتاريــخ ‪1430/7/7‬ه ـ مبوجــب وثيقــة عقــد‬\n‫النــكاح الصــادرة مــن احملكمــة العامــة يف اخلبــر برقــم ‪ 67/1‬وتاريــخ‬\n‫‪1430/7/7‬ه ـ ودخــل بهــا الدخــول الشــرعي‪ ،‬ثــم إنــه قــد طلــق موكلتــي‬\n‫بتاريــخ ‪1430/9/1‬ه ـ وهــي حامــل منــه مبوجــب صــك الطــاق الصــادر‬\n‫مــن احملكمــة العامــة يف اخلبــر برقــم ‪........‬وتاريــخ ‪1430/9/1‬ه ـ املجلــد‬\n‫الثانــي ثــم إن موكلتــي وضعــت حملهــا منــه بنت ـ ًا بتاريــخ ‪1431/5/3‬ه ـ‬\n‫ومت تســميتها ‪ ،‬وإن املدعــى عليــه ال ينفــق علــى ابنتــه املذكــورة ســوى‬\n‫يف العيديــن فإنــه يســلمها ثالثمائــة ريــال فقــط أحيان ـ ًا ‪ ،‬لــذا أطلــب‬\n‫تقديــر نفقــة املثــل للطفلــة ‪........‬وإلــزام املدعــى عليــه بدفعهــا ملوكلتــي‬\n‫لكــي تنفقهــا علــى الطفلــة ‪،........‬هــذه دعــواي ‪ ،‬وباســتجواب املدعــى‬\n\n                                                                                          ‫‪182‬‬\n\f      ‫عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي وكالــة يف دعــواه مــن أننــي ســبق‬\n      ‫أن تزوجــت موكلتــه بالعقــد الصحيــح يف ‪1430/7/7‬ه ـ ودخلــت بهــا‬\n      ‫الدخــول الشــرعي وأننــي طلقتهــا يف ‪1430/9/1‬ه ـ وهــي حامــل بابنتــي‬\n      ‫وأنهــا وضعــت حملهــا يف ‪1431/5/3‬ه ـ فهــذا صحيــح وأمــا مــا ذكــره‬\n      ‫مــن أننــي ال أنفــق علــى ابنتــي فهــذا غيــر صحيــح وأنــا مســتعد باإلنفــاق‬\n      ‫عليهــا حســب قدرتــي املاديــة حيــث إننــي متقاعــد ودخلــي الشــهري‬\n      ‫هــو راتبــي التقاعــدي البالــغ ألفــان وخمســمائة وثالثــة ريــاالت هــذا مــا‬\n      ‫أجــاب بــه ‪ ،‬ثــم إنــه يف جلســة أخــرى حضــرت املدعيــة أصالــة ســعودية‬\n      ‫اجلنســية مبوجــب الســجل املدنــي رقــم برفقــة شــقيقها املعــرف بهــا‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وقــال املدعــى عليــه إننــي‬\n      ‫ال أســتطيع أن أدفــع نفقــة ال بنتــي ســوى مائتــن أو ثالثمائــة ريــال شــهري ًا‬\n      ‫بســبب ضعــف حالتــي املاديــة ‪ ،‬هــذا مــا قالــه ‪ ،‬وبعرضــه علــى املدعيــة‬\n      ‫قالــت ‪ :‬إن كفايــة البنــت مــن النفقــة ال تقــل عــن خمســمائة ريــال فأطلــب‬\n      ‫أن تكــون النفقــة الشــهرية لهــا خمســمائة ريــال ‪ ،‬هــذا مــا قالتــه ‪ ،‬وبعــد‬\n      ‫ذلــك رفعــت اجللســة للكتابــة لهيئــة النظــر يف احملكمــة لتقديــر نفقــة‬\n      ‫املثــل الشــهرية للطفلــة ‪ ........‬واإلفــادة وقبــل قفــل اجللســة قــررت املدعيــة‬\n      ‫قائلــة ‪ :‬لقــد أقمــت شــقيقي ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n      ‫ا ينــوب عنــي يف املرافعــة يف هــذه القضيــة ولــه‬  ‫رقــم هــذا احلاضــر وكيـ ً‬\n      ‫حــق املخاصمــة واملدافعــة واإلقــرار واإلنــكار والصلــح والتنــازل وقبــول‬\n      ‫احلكــم واالعتــراض عليــه وتقــدمي البيانــات والــرد عليهــا واالســتالم‬\n      ‫والتســليم والتوقيــع نيابــة عنــي يف ذلــك ‪ ،‬هــذا مــا قررتــه ‪ ،‬بحضــور‬\n      ‫شــقيقها واملدعــى عليــه املذكوريــن أعــاه وعليــه جــرى التصديــق‪ ،‬ثــم‬\n      ‫إنــه يف جلســة أخــرى حضــر املدعــي وكالــة واملدعــى عليــه ‪ ،‬وكان‬\n\n\n‫‪183‬‬\n\f‫قــد جــرى منــا الكتابــة لهيئــة النظــر يف احملكمــة لتقديــر نفقــة املثــل‬\n‫للطفلــة ‪........‬بخطابنــا رقــم ‪ 331442723‬وتاريــخ ‪1433/10/29‬ه ـ ‪،‬‬\n‫فوردنــا منهــم اجلــواب رقــم ‪ 331442723‬يف ‪1433/12/1‬ه ـ مرفق ـ ًا بــه‬\n‫قــرار هيئــة النظــر رقــم ‪ 300‬يف ‪1433/12/1‬ه ـ املتضمــن أن نفقــة املثــل‬\n‫ـاء علــى مــا تقــدم‬ ‫للطفلــة ‪........‬هــو أربعمائــة ريــال كل شــهر أه ـ ‪ .‬فبنـ ً‬\n‫مــن الدعــوى واإلجابــة ونظــر ًا ملــا قــرره املدعــى عليــه مــن إنــه مســتعد‬\n‫باإلنفــاق علــى ابنتــه ‪ ...‬حســب قدرتــه ونظــر ًا ملــا ورد يف قــرار هيئــة النظــر‬\n‫ولقولــه تعالــى ‪ ( :‬لينفــق ذو ســعة مــن ســعته ) ‪ ،‬فقــد حكمــت علــى‬\n‫املدعــى عليــه بــأن يدفــع نفقــة شــهرية البنتــه مقدارهــا أربعمائــة ريــال‬\n‫تســلم للمدعيــة والــدة الطفلــة كل شــهر لتنفقهــا علــى الطفلــة ‪،........‬‬\n‫وهــذا احلكــم مشــمول بالنفــاذ املعجــل ‪ ،‬وبعــرض احلكم علــى الطرفني‬\n‫قــرر املدعــي وكالــة القناعــة باحلكــم وقــرر املدعــى عليــه عــدم القناعــة‬\n‫فأفهمتــه بأنــه ســيتم تســليمه نســخة مــن صــك احلكــم بعــد قليــل لتقــدمي‬\n‫اعتراضــه عليــه خــال مــدة أقصاهــا ثالثــون يومـ ًا إن لــم يقــدم اعتراضــه‬\n‫خاللهــا يســقط حقــه يف االعتــراض ويكتســب احلكــم القطعية‪،‬وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                  ‫‪1434/1/21‬ه ـ ‪.‬‬\n‫تظهيــرات دائــرة األحــوال الشــخصية الثانيــة مبحكمــة االســتئناف‬\n                                                             ‫باملنطقــة الشــرقية ‪:‬‬\n‫احلمــد هلل وحــده وبعــد ‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪3419050‬‬\n‫وتاريــخ ‪1434/1/21‬ه ـ الصــادر مــن فضيلــة القاضــي الشــيخ واصدرنــا‬\n‫القــرار رقــم ‪/34171339‬ش‪/1‬أ وتاريــخ ‪1434/3/24‬ه ـ املتضمــن‬\n                  ‫املصادقــة علــى حكــم فضيلتــه ‪ .‬حــرر يف ‪1434/4/7‬هــ‪.‬‬\n\n\n                                                                                          ‫‪184‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n      ‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/363479‬ش‪ 2‬وتاريــخ‬\n      ‫‪1434/2/12‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامة مبحافظة‬\n      ‫القطيــف برقــم ‪ 331442723‬وتاريــخ ‪1434/2/9‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلــة القاضــي بهــا الشــيخ‪ ......... /‬املســجل برقــم‬\n      ‫‪ 3419050‬وتاريــخ ‪1434/1/21‬ه ـ اخلــاص بدعــوى‪........ /‬ضــد‪......../‬‬\n      ‫يف قضيــة نفقــة وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n                                                                      ‫وأوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى حكــم فضيلتــه‪ .‬واهلل املوفــق وصلــى اهلل علــى‬\n                   ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/3/24‬ه ـ‬\n\n\n\n\n‫‪185‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":181,"source_page_end":185,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2cfc8eef6b597130124ef3ca5256af558d0c7ab07b5927b5ef0b6f49fbcbf65b","normalized_text_hash":"5fc55c4402cd28f66636b1f1919a2707362ce5c0e6fa530d0f2c5d7152af3fc1","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p181-3419050"},{"id":"334a219c-75ba-54ba-b31a-db0faf8d42ec","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة والد بنفقته من ابنته -النفقة ال جتب على البنت ألبيها خاصة وهي يف ذمة زوج -صرف نظر عن الدعوى.","document_number":"34207900","case_number":"33511620","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باألحساء ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/6","year":"1434","subject":"نفقة -مطالبة والد بنفقته من ابنته -النفقة ال جتب على البنت ألبيها خاصة وهي يف ذمة زوج -صرف نظر عن الدعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/5/6 :‬هـ‬\n             ‫ُ‬                      ‫َر ْق ُم َّ‬\n                      ‫الص ِّك‪34207900 :‬‬\n                     ‫َر ْق ُم الدعوى‪33511620 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34373143‬تاريخه‪1434/11/27 :‬هـ‬\n\n\n\n  ‫نفقــة ‪ -‬مطالبــة والــد بنفقتــه مــن ابنتــه ‪ -‬النفقــة ال جتــب علــى البنــت‬\n                ‫ألبيهــا خاصــة وهــي يف ذمــة زوج ‪ -‬صــرف نظــر عــن الدعــوى‪.‬‬\n\n\n\n\n  ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة الــواردة يف‬\n                                                               ‫تســبيب باحلكــم ‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي ضــد املدعــى عليــه وكالــة أن املدعــى عليهــا أصالــة‬\n  ‫ابنتــه مــن مواليــد ‪1414/6/17‬ه ـ وأنــه ســبق وأن قــام بتســجيلها يف‬\n  ‫املدرســة وجميــع مصاريفهــا الدراســية ونفقتهــا ودراســتها اخلاصــة باللغــة‬\n  ‫االجنليزيــة وكانــت مــن حســابه اخلــاص وقــد ذهبــت املدعــى عليهــا إلــى‬\n  ‫بيــت أمهــا ولــم ترجــع وقامــت أمهــا باملطالبــة بنفقــة ابنتهــا وحكــم لهــا‬\n  ‫بالنفقــة ولــم يكتســب احلكــم القطعيــة وقــرر املدعــي أن ابنتــه متزوجــة‬\n  ‫يف الوقــت احلاضــر وتــدرس يف قســم الطــب ومكافأتهــا الشــهرية‬\n  ‫تقــارب ثلــث دخلــه وطالــب املدعــي بإلــزام املدعــى عليهــا بالنفقــة مــن‬\n  ‫تاريــخ دخــول ابنتــه اجلامعــة ‪ -‬أجــاب املدعــى عليــه بالوكالــة باملصادقــة‬\n  ‫علــى الدعــوى ســوى أنــه ال يوافــق علــى النفقــة الن املدعــى عليهــا الزالــت‬\n  ‫طالبــة باجلامعــة ‪ -‬قــرر ناظــر القضيــة ومبــا أن املدعــى عليهــا ال تــزال‬\n                                                                                         ‫‪186‬‬\n\f      ‫تــدرس يف اجلامعــة ومتزوجــة ومعلــوم أن النفقــة ال جتــب علــى البنــت‬\n      ‫ألبيهــا خصوص ـ ًا أنهــا يف ذمــة زوجهــا والراتــب إمنــا هــو حلــث ومســاعدة‬\n      ‫الطــاب علــى إكمــال التعليــم فقــد صــدر احلكــم بصــرف النظــر‬\n      ‫عــن الدعــوى ‪-‬اعتــرض املدعــي علــى احلكــم ‪ -‬صــدر قــرار محكمــة‬\n                                               ‫االســتئناف باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫العامــة‬\n         ‫ّ‬     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n      ‫باالحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة مســاعد رئيــس‬\n      ‫احملكمــة العامــة باألحســاء برقم ‪ 33511620‬وتاريــخ ‪1433/08/07‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331488168‬وتاريــخ ‪1433/08/07‬ه ـ‬\n      ‫حضــر‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ......‬وحضــر‬\n      ‫حلضــوره ‪ ......‬ســعودي مبوجــب الســجل املدنــي رقــم ‪ ......‬حــال كونــه‬\n      ‫ا عــن املدعــى عليهــا ‪ ......‬ســعودية مبوجــب الســجل املدنــي‬        ‫وكي ـ ً‬\n      ‫رقــم‪ ......‬مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل األحســاء‬\n      ‫الثانيــة برقــم ‪ ........‬تاريــخ ‪1433/03/02‬ه ـ واملخولــة لــه حــق املخاصمــة‬\n      ‫واملرافعــة واملدافعــة ويف إقامــة الدعــوى وقبــول احلكــم أو اإلعتــراض‬\n      ‫عليــه واإلقــرار واإلنــكار وغيــر ذلــك وبســؤال املدعــي عــن دعــواه قــال‬\n      ‫إن املدعــى عليهــا ابنتــي مــن مواليــد ‪1414/6/17‬ه ـ وتبلــغ مــن العمــر‬\n      ‫تســعة عشــر عام ـ ًا وســبق وأن قمــت بتســجيلها يف املدرســة وكانــت‬\n      ‫جميــع مصاريفهــا الدراســية مبــا يف ذلــك النفقــة ودراســتها اخلاصــة‬\n      ‫باللغــة اإلجنليزيــة كان كل ذلــك عــن طريقــي ومــن مالــي حتــى ذهبــت‬\n      ‫لبيــت أهــل أمهــا للزيــارة بتاريــخ ‪1431/1/14‬ه ـ ولــم ترجــع لبيــت والدها‬\n‫‪187‬‬\n\f‫بــل قامــت مطلقتــي وهــي والدتهــا تطالبنــي بنفقــة البنتــي رغــم جلوســها‬\n‫بغيــر رضــا منــي ومطالبتــي لهــا بالعــودة إال أن القاضــي حكــم ملطلقتــي‬\n‫بنفقــة أكثــر مــن دخلــي ولــم يكتســب احلكــم القطعيــة بعــد واملدعــى‬\n‫عليهــا يف الوقــت احلاضــر متزوجــة وتقيــم يف األحســاء وتــدرس يف جامعــة‬\n‫‪ ......‬قســم ‪ ......‬وتســتلم مكافــأة شــهرية تقــارب ثلــث دخلــي لــذا أطلــب‬\n‫إلــزام ابنتــي بالنفقــة علـ ّـي مــن تاريــخ تســجيلها باجلامعــة لقــاء مــا قمــت‬\n‫جتاههــا خــال تلــك الســنوات علمـ ًا بأنهــا ال تقــوم بزيارتــي هــذه دعــواي‬\n‫وبعــرض الدعــوى علــى املدعــى عليــه وكالــة قــال إن املدعــى عليهــا ابنــة‬\n‫هــذا احلاضــر املدعــي متزوجــة وتقيــم مــع زوجهــا يف مدينــة الدمــام وال‬\n‫تــزال طالبــة يف اجلامعــة وال تصــادق علــى دعــوى املدعــي يف املطالبــة‬\n‫ـاء علــى مــا تقــدم‬‫بالنفقــة لكونهــا ال تــزال طالبــة هكــذا أجــاب فبنـ ً‬\n‫مــن الدعــوى واإلجابــة ونظــر ًا لكــون املدعــي يطالــب املدعــى عليهــا‬\n‫بالنفقــة عليــه وتصــادق الطرفــان علــى أن املدعــى عليهــا ال تــزال تــدرس‬\n‫يف اجلامعــة ومتزوجــة ومعلــوم أن النفقــة ال جتــب علــى البنــت البيهــا‬\n‫خصوص ـ ًا وأنهــا يف ذمــة زوجهــا والراتــب الــذي تأخــذه مــن اجلامعــة إمنــا‬\n‫هــو حلــث ومســاعدة الطــاب علــى إكمــال تعليمهــم لــذا فقــد حكمــت‬\n‫بصــرف النظــر عــن دعــوى املدعــي وبعــرض احلكــم علــى املدعــي قــرر‬\n‫املعارضــة عليــه وطلــب محكمــة االســتئناف فأفهمتــه مبراجعتنــا بتاريخ‬\n‫‪1434/5/19‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي اإلعتــراض عليــه‬\n‫خــال املــدة النظاميــة وهــي ثالثــون يوم ـ ًا مــن تاريــخ اســتالم النســخة‬\n‫وأنهــا إذا مضــت املــدة النظاميــة لإلعتــراض دون تقــدمي املعارضة فســوف‬\n‫يكتســب احلكــم الصفــة القطعيــة بذلــك وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/05/06‬هـ‪.‬‬\n\n\n                                                                                        ‫‪188‬‬\n\f      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n      ‫الشــخصية األولــى يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n      ‫املعاملــة املقيــدة باحملكمــة برقــم ‪/34/1360407‬ش‪ 1‬وتاريــخ‬\n      ‫‪1434/6/6‬ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫األحســاء برقــم ‪ 33/1488168‬وتاريــخ ‪1434/5/29‬ه ـ املرفــق بهــا‬\n      ‫الصــك الصــادر مــن فضيل ــة القاضــي بهــا الشــيخ‪ ......‬املســجل برقــم‬\n      ‫‪ 34207900‬وتاريــخ ‪1434/5/6‬ه ـ اخلــاص بدعــوى‪ ....../‬ضــد‪....../‬‬\n      ‫يف قضيــة نفقــة‪ .‬وقــد تضمــن الصــك حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة الضبــط والالئحــة االعتراضيــة‬\n      ‫وأوراق املعاملــة قررنــا املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/11/ 27‬هــ‪.‬‬\n\n\n\n\n‫‪189‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":186,"source_page_end":189,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5f4b2aee1c18dc9fe7c1a82bd13ce9c20060ae99ce4e3e8031cfd89ef3b19495","normalized_text_hash":"94ba2ef5e1302ed2bf634689058102a9d43f12ca03843e585a30cfb67e0729ea","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p186-34207900"},{"id":"6b9c68d1-bef4-5208-8e9a-e262e3b65b29","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة أوالدها -مطالبة أم بأجرة سكن أوالدها -تعريف النفقة -تقدير النفقة عن طريق قسم اخلبراء -احلكم على األب بالنفقة وأجرة املسكن.","document_number":"34250214","case_number":"33544548","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/24","year":"1434","subject":"نفقة -مطالبة أم بنفقة أوالدها -مطالبة أم بأجرة سكن أوالدها -تعريف النفقة -تقدير النفقة عن طريق قسم اخلبراء -احلكم على األب بالنفقة وأجرة املسكن.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/6/24 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34250214 :‬‬\n                   ‫َر ْق ُم الدعوى‪33544548 :‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n           ‫‪ 34307338‬تاريخه‪1434/8/28 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬مطالبــة أم بنفقــة أوالدهــا ‪ -‬مطالبــة أم بأجــرة ســكن أوالدهــا‬\n‫‪ -‬تعريــف النفقــة ‪ -‬تقديــر النفقــة عــن طريــق قســم اخلبــراء ‪ -‬احلكــم‬\n                                     ‫علــى األب بالنفقــة وأجــرة املســكن‪.‬‬\n\n\n\n\n‫قــال يف كشــاف القنــاع ‪ 13/13‬عنــد تعريــف النفقــة هــي (( كفايــة مــن‬\n                                   ‫ميونــه خبــز ًا وأدمـ ًا وكســوة ومســكن ًا ))‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه حيــث كان زوجهــا ورزقــت منــه‬\n‫بولديــن همــا يف حضانتهــا وقــد طلقهــا املدعــى عليــه وطالبــت املدعيــة‬\n‫باحلكــم علــى املدعــى عليــه بدفــع نفقــة لــأوالد كمــا أنهــا تســكن‬\n‫يف شــقة للمدعــى عليــه وطالبــت أال يخــرج ولديهــا مــن الشــقة ‪ -‬أجــاب‬\n‫املدعــى عليــه باملصادقــة علــى الدعــوى وقــرر أنــه مســتعد بتســليم نفقــة‬\n‫شــهرية قدرهــا خمســمائة ريــال وطلــب خروجهــا مــن املنــزل الــذي‬\n‫تســكن فيــه وقــرر اســتعداده دفــع مبلــغ اثنــي عشــر ألــف ريــال ســنوي ًا‬\n‫أجــرة ســكن يف خميــس مشــيط حتــى تنتهــي احلضانــة ‪ -‬مت الكتابــة‬\n‫لقســم اخلبــراء ومت تقديــر نفقــة الولديــن وأجــرة الســكن شــهري ًا بألــف‬\n‫وثمامنائــة ريــال ‪ -‬مت الصلــح بــن الطرفــن علــى تقديــر النفقــة الســابقة‬\n                                                                                     ‫‪190‬‬\n\f      ‫ـاء علــى مــا‬\n                  ‫مبلغ ـ ًا قــدره خمســة آالف ريــال ‪ -‬قــرر ناظــر القضيــة أنــه بنـ ً‬\n      ‫جــاء يف كشــاف القنــاع عنــد تعريــف النفقــة هــي (( كفايــة مــن ميونــه‬\n      ‫ـاء علــى تقديــر قســم اخلبــراء‬ ‫خبــز ًا وأدم ـ ًا وكســوة ومســكن ًا )) وبنـ ً‬\n      ‫فقــد صــدر احلكــم بإلــزام املدعــى عليــه بــأن يســلم نفقــة شــهرية قدرهــا‬\n      ‫ســتمائة ريــال لــكل واحــد مــن الولديــن مــن ‪1434/7/25‬ه ـ ودفــع‬\n      ‫أجــرة ســكن لهمــا شــهري ًا قدرهــا ســتمائة ريــال وتســليمها للمدعيــة‬\n      ‫عنــد إخــاء شــقة املدعــى عليــه ‪ -‬صــدر قــرار محكمــة االســتئناف‬\n                                                             ‫باملصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة‬\n      ‫العامــة بخميــس مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة بخميــس مشــيط برقــم ‪ 33544548‬وتاريــخ‬\n      ‫‪ 1433/08/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331596545‬وتاريــخ‬\n      ‫‪1433/08/25‬ه ـ واملتعلقــة بدعــوى (‪ ).....‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ ).....‬ضــد (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ ).....‬ففــي يــوم األحــد املوافــق ‪1433/9/10‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة العاشــرة والنصــف وفيهــا حضــر الطرفــان وادعــت‬\n      ‫املدعيــة قائلــة إننــي تزوجــت مــن املدعــى عليــه بتاريــخ ‪1424/9/5‬ه ـ‬\n      ‫بواليــة أخــي وأجنبــت مــن املدعــى عليــه ولديــن (‪ ).....‬املولــود بتاريــخ‬\n      ‫‪1427/1/2‬ه ـ و(‪ ).........‬املولــودة بتاريــخ ‪1430/3/22‬ه ـ وقــد طلقنــي‬\n      ‫بتاريــخ ‪1433/7/6‬ه ـ مبوجــب الصــك الصــادر مــن هــذه احملكمــة‬\n      ‫برقــم ‪ 33354049‬يف ‪1433/7/23‬ه ـ والولــدان اآلن يف حضانتــي‬\n‫‪191‬‬\n\f‫أطلــب إلــزام املدعــي بدفــع نفقــة للولديــن وأن ال يخرجنــا مــن املنــزل‬\n‫الــذي نســكن فيــه هكــذا ادعــت وبســؤال املدعــى عليــه عــن دعــوى‬\n‫املدعيــة أجــاب قائــا مــا ذكرتــه املدعيــة يف دعواهــا مــن زواجــي بهــا‬\n‫وإجنابهــا لولدينــا وطالقــي لهــا فذلــك صحيــح وأمــا طلبهــا النفقــة فأنــا‬\n‫مســتعد بإعطائهــا نفقــة للولديــن قدرهــا خمســمائة (‪)500‬ريــال شــهريا‬\n‫وأمــا بقاؤهــا يف منزلــي الــذي تســكن فيــه فأنــا أريدهــا أن تخــرج منــه‬\n‫ومســتعد بــأن أتبــرع مببلــغ وقــدره اثنــا عشــر ألــف (‪ )12000‬ريــال ســنويا‬\n‫يكــون أجــرة لســكن يكــون يف خميــس مشــيط وذلــك حتــى تنتهــي‬\n‫احلضانــة هكــذا أجــاب وبعــرض ذلــك علــى املدعيــة أجابــت قائلــة إن‬\n‫النفقــة التــي اســتعد بهــا املدعــى عليــه قليلــة وكذلــك مبلــغ اإليجــار‬\n‫وهــو رجــل موســر لذلــك ال أقبــل بهــا هكــذا أجابــت وعليــه فقــد قــررت‬\n‫الكتابــة لقســم اخلبــراء لتقديــر نفقــة الولديــن وأجــرة الســكن لهمــا‬\n‫ويف جلســة أخــرى حضــرت املدعيــة واملدعــى عليــه وقــد عــادت املعاملــة‬\n‫مــن قســم اخلبــراء بقرارهــم رقــم ‪ 331596545‬يف ‪1433/11/15‬ه ـ‬\n‫واملتضمــن ( عليــه نفيــد فضيلتكــم بأنــه يتقــدر نفقــة الفــرد الواحــد‬\n‫منهمــا لليــوم الواحــد عشــرون (‪)20‬ريــال ومجموعهــا يف الشــهر للفــرد‬\n‫الواحــد منهمــا مبلــغ ســتمائة (‪ )600‬ريــال ومجمــوع النفقــة يف الشــهر‬\n‫الواحــد للولديــن مبلــغ ألــف ومائتــا (‪ )1200‬ريــال وتتقــدر أجــرة الســكن‬\n‫يف الشــهر مببلــغ ألــف (‪ )1000‬ريــال ومجمــوع النفقــة لــأوالد والســكن‬\n‫ألفــان ومائتــا (‪ )2200‬ريــال هــذا ماجــرى تقديــره واإلجتهــاد بــه حســب‬\n‫حــال املنفــق وبــاهلل التوفيــق عضــوي قســم اخلبــراء) انتهــى وبعرضــه علــى‬\n‫املدعيــة قــررت القناعــة بــه وبعرضــه علــى املدعــى عليــه قــرر قائــا إننــي‬\n‫غيــر مقتنــع بالقــرار املذكــور يف النفقــة وأجــرة الســكن ألننــي لــم‬\n\n\n                                                                                     ‫‪192‬‬\n\f      ‫أجلــس مــع قســم اخلبــراء حتــى يتمكنــوا مــن حتديدهــا كمــا أن النفقــة‬\n      ‫كثيــرة فلــدي إلتزامــات ماليــة أخــرى ولــدي عائلــة وديــون وأمــا أجــرة‬\n      ‫الســكن فإنهــا ال تلزمنــي وهــي مســئولة عــن تأمــن الســكن ألنهمــا يف‬\n      ‫حضانتهــا أطلــب إعــادة تقديــر النفقــة بحضــوري هكــذا أجــاب وعليــه‬\n      ‫فقــد قــررت إعــادة الكتابــة لقســم اخلبــراء لتحديــد النفقــة بعــد حضــور‬\n      ‫املدعــى عليــه لديهــم وســماع مــا لديــه وتقــدمي مــا يثبــت مــا ذكــره ويف‬\n      ‫جلســة أخــرى حضــرت املدعيــة واملدعــى عليــه وقد عادت لنــا املعاملة من‬\n      ‫قســم اخلبــراء بقرارهــم رقــم ‪ 331596545‬يف ‪1434/5/4‬ه ـ املتضمــن (‬\n      ‫نفيدكــم بأنــه ســبق وأن قــدرت نفقــة األوالد وأجــرة الســكن لهمــا‬\n      ‫مبوجــب قرارنــا الســابق ‪ 331596646‬يف ‪1434/1/11‬ه ـ املرفــق‬\n      ‫بنــاء علــى املســتندات واإلثباتــات املقدمــة مــن املدعــى عليــه املرفقــة‬\n      ‫وجــرى إفهامــه بذلــك يف حينــه وقناعتــه وأعيــدت لنــا هــذه املعاملــة مــرة‬\n      ‫أخــرى وقــد حضــر املذكــور لدينــا وأفهمنــاه مبضمــون ذلــك وقناعتــه‬\n      ‫ونفقــة األوالد وأجــرة ســكنهما موضحــة بالقــرار املشــار إليــه عضــوي‬\n      ‫هيئــة اخلبــراء توقيعهمــا) انتهــى وجــرى االطــاع علــى القــرار املشــار‬\n      ‫إليــه رقــم ‪ 331596646‬يف ‪1434/1/11‬ه ـ ونــص احلاجــة منــه (نفيــد‬\n      ‫فضيلتكــم بــأن املدعــى عليــه قــد حضــر لدينــا وأرفــق تعريــف مبقــدار‬\n      ‫راتبــه وقــد جــرى تقديــر نفقــة األوالد مــن قبلنــا مبوجــب قرارنــا الســابق‬\n      ‫رقــم ‪ 331596545‬يف ‪1433/11/15‬ه ـ مبــا يتناســب مــع مصروفــات‬\n      ‫واحتياجــات األوالد وحــال املنفــق وقــد أوضحنــا لــه ذلــك وجــرى التفاهــم‬\n      ‫معــه يف موضــوع الســكن بحيــث يســكنون األوالد مــع أمهمــا فنــرى‪:‬‬\n      ‫يكــون علــى األب مبلــغ ســتمائة (‪ )600‬ريــال مقابــل ســكن األوالد مــع‬\n      ‫األم والباقــي مقابــل ســكن األم حيــث يصبــح كامــل املبلــغ يف الشــهر‬\n\n\n‫‪193‬‬\n\f‫مــن نفقــة وســكن علــى األب مبلــغ ألــف وثمامنائــة (‪ )1800‬ريــال بــدال‬\n‫مــن ألفــن ومائتــي (‪ )2200‬ريــال الــوارد بقرارنــا الســابق هــذا مــا جــرى‬\n‫عملــه عضــوي هيئــة اخلبــراء توقيعهمــا) انتهــى وبعرضــه علــى املدعيــة‬\n‫قــررت عــدم قناعتهــا بــه وقــرر املدعــي عــدم القناعــة وقــرر قائــا إننــي‬\n‫مســتعد بدفــع نفقــة شــهرية قدرهــا (‪ )500‬خمســمائة ريــال لــكل واحــد‬\n‫مــن الولديــن ومبلــغ قــدره (‪ )6000‬ســتة آالف ريــال أجــرة ســنوية ويكــون‬\n‫عليهــا باقــي أجــرة البيــت الــذي ترغبــه وتخلي الشــقة يف عمارتي هكذا‬\n‫قــرر وبعرضــه عليهــا قــررت عــدم قبولها بذلك ويف نفس اجللســة اصطلح‬\n‫الطرفــان أن يدفــع املدعــى عليــه عــن النفقــة الســابقة حتــى هــذا الشــهر‬\n‫جمــادى الثانيــة عــام ‪1434‬ه ـ مبلغــا وقــدره خمســة آالف ريــال بتاريــخ‬\n‫‪1434/6/26‬ه ـ هكــذا اصطحــا وبســؤال املدعيــة عــن أجــرة الســكن‬\n‫أجابــت قائلــة إننــي أقيــم يف شــقة للمدعــى عليــه ومســتعدة بإخالئهــا‬\n‫علــى أن يدفــع األجــرة عــن ولديــه هكــذا أجابــت فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة ونظــرا ألن الطرفــن لــم يتوصــا إلــى اتفــاق علــى‬\n‫النفقــة وأجــرة الســكن قــال يف كشــاف القنــاع ‪ 13/13‬عنــد تعريــف‬\n‫النفقــة هــي (كفايــة مــن ميونــه خبــزا وأدمــا وكســوة ومســكنا) وبنــاء‬\n‫علــى تقديــر قســم اخلبــراء للنفقــة وأجــرة الســكن التــي تلــزم املدعــى‬\n‫عليــه لذلــك كلــه فقــد ألزمــت املدعــى عليــه مبــا يلــي أوال‪ :‬دفــع نفقــة‬\n‫شــهرية وقدرهــا (‪ )600‬ســتمائة ريــال لــكل واحــد مــن ولديــه ابتــداء مــن‬\n‫تاريــخ ‪1434/7/25‬ه ـ ثانيــا ‪ :‬دفــع أجــرة ســكن لهمــا شــهرية قدرهــا‬\n‫(‪ )600‬ســتمائة ريــال وتســليمها للمدعيــة عنــد إخــاء شــقة املدعــى عليــه‬\n‫هــذا مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى الطرفــن قــررت املدعيــة‬\n‫القناعــة بــه وقــرر املدعــى عليــه عــدم القناعــة بــه واســتعد بتقــدمي الئحــة‬\n\n\n                                                                                       ‫‪194‬‬\n\f      ‫اعتراضيــة فأجيــب لطلبــه وأفهــم مبراجعتنــا خــال عشــرة أيــام الســتالم‬\n      ‫نســخة احلكــم لتقــدمي اعتراضــه خــال ثالثــن يومــا مــن تاريخــه وإال‬\n      ‫ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة ومت رفــع اجللســة‬\n      ‫الســاعة الثانيــة عشــرة وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/06/19‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي القائــم بعمــل املكتــب‬\n      ‫القضائــي اخلامــس يف احملكمــة العامــة بخميــس مشــيط وعليــه‬\n      ‫ففــي يــوم اإلثنــن املوافــق ‪1434/10/12‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫التاســعة وقــد وردتنــا كامــل املعاملــة مــن محكمــة اإلســتئناف بعســير‬\n      ‫برقــم ‪ 341645271‬يف ‪1434/9/8‬ه ـ وبرفقهــا قــرار التصديــق رقــم‬\n      ‫‪ 34307338‬يف ‪1434/8/28‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة‬\n      ‫علــى احلكــم باألكثريــة واهلل املوفــق وصلــى اهلل وســلم علــى نبينــا‬\n      ‫محمــد وآلــه وصحبــه وســلم قاضــي اســتئناف (‪ ).....‬لــي وجهــة نظــر‬\n      ‫ختمــه وتوقيعــه قاضــي اســتئناف (‪ ).....‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n      ‫(‪ ).....‬ختمــه وتوقيعــه) انتهــى وعليــه فقــد قــررت إحلاقــه بالضبط وســجله‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                       ‫حــرر يف ‪1434/10/12‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحن قضــاة الدائرة املختصة بتدقيق‬\n      ‫قضايــا األحــوال الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال‬\n      ‫مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة لهــذه‬\n      ‫احملكمــة مــن فضيلــة رئيــس احملكمــة العامــة بخميــس مشــيط برقــم‬\n      ‫‪ 331596545‬وتاريــخ‪1434/6/ 26‬ه ـ املرفــق بهــا الصــك الصــادر مــن‬\n\n\n‫‪195‬‬\n\f‫فضيلــة الشــيخ‪ ....../‬املســجل برقــم ‪ 34250214‬وتاريخ‪1434/6/24‬ه ـ‬\n‫اخلاصــة بدعــوى ضــد بشــأن نفقــة علــى الصفــة املوضحــة بالصــك‬\n‫املتضمــن حكــم فضيلتــه مبــا هــو مــدون بباطنــه وبدراســة الصــك‬\n‫وصــورة ضبطــه والالئحــة االعتراضيــه وأوراق املعاملــة تقــررت املوافقــة‬\n‫علــى احلكــم باألكثريــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n‫وآلــه وصحبــه وســلم ‪ .‬دائــرة األحــوال الشــخصية واألوقــاف والوصايــا‬\n                                                     ‫والقصــار وبيــوت املــال ‪.‬‬\n\n\n\n\n                                                                                   ‫‪196‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":190,"source_page_end":196,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3e3da027be48ad2e40af937a0d14443f74391431028d756bb479fd4d02096e08","normalized_text_hash":"aaaca7f4ea1ec7587d5d41f0b183ecfd3a1d2d51d450600ae3dd94b7fac62a0b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p190-34250214"},{"id":"a38b7fa9-63c6-5f48-885d-a8b7343ae5f3","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة األم بنفقة ابنتها املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء بحسب العرف والعادة -إلزام املدعى عليه بنفقة الطفل املاضية واملستقبلية وشمول احلكم بالنفاذ املعجل .","document_number":"34167121","case_number":"33634070","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/21","year":"1434","subject":"نفقة -مطالبة األم بنفقة ابنتها املاضية واملستقبلية -تقدير النفقة عن طريق قسم اخلبراء بحسب العرف والعادة -إلزام املدعى عليه بنفقة الطفل املاضية واملستقبلية وشمول احلكم بالنفاذ املعجل .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/21 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪34167121 :‬‬\n                          ‫َر ْق ُم الدعوى‪33634070 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n                   ‫‪ 34313885‬تاريخه‪1434/9/7 :‬هـ‬\n\n\n\n      ‫نفقة ‪ -‬مطالبة األم بنفقة ابنتها املاضية واملستقبلية ‪ -‬تقدير النفقة‬\n      ‫عــن طريــق قســم اخلبــراء بحســب العــرف والعــادة ‪ -‬إلــزام املدعــى عليــه‬\n          ‫بنفقــة الطفــل املاضيــة واملســتقبلية وشــمول احلكــم بالنفــاذ املعجل ‪.‬‬\n\n\n\n\n                                            ‫املادة ‪/199‬ب من نظام املرافعات الشرعية‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليــه بأنــه كان زوجــا لهــا وقــد طلقهــا‬\n      ‫وأجنبــت منــه ابنــة وعمرهــا خمســة أعــوام وهــي حتــت حضانتهــا وال‬\n      ‫زالــت صغيــرة لــم ينفــق عليهــا منــذ والدتهــا وأنهــا التــي أنفقــت عليهــا‬\n      ‫حتــى تاريــخ هــذه اجللســة وتطلــب احلكــم بإلــزام املدعــى عليــه بدفــع‬\n      ‫النفقــة املاضيــة واملســتقبلية ‪ -‬أجــاب املدعــى عليــه باملصادقــة علــى‬\n      ‫الــزواج واإلجنــاب والطــاق أمــا النفقــة فقــد أنفــق عليهــا مــدة ســنة‬\n      ‫ونصــف ثــم انقطــع عــن النفقــة لكــون املدعيــة لــم تســمح لــه برؤيــة‬\n      ‫البنــت إال ثوانــي كمــا أنــه يهــان إذا حضــر للزيــارة ‪ -‬قــرر املدعــى‬\n      ‫عليــه بــأن راتبــه عشــرة آالف ومائتــن وخمســة وســبعني ريــا ًال ‪ -‬جــرت‬\n      ‫الكتابــة لهيئــة النظــر لتقديــر النفقــة حســب العــرف والعــادة ‪ -‬ورد‬\n\n‫‪197‬‬\n\f‫جوابهــم بتحديــد ثمامنائــة ريــال للنفقــة املاضيــة وألــف وســتمائة ريــال‬\n‫للنفقــة املســتقبلية ‪ -‬املدعيــة قــررت بأنهــا تنفــق علــى ابنتهــا مــن تاريــخ‬\n‫املخالعــة يف ‪1429/7/10‬ه ـ ‪ -‬ليــس للمدعــى عليــه بينــة علــى انفاقــه‬\n‫علــى البنــت مــدة ســنة ونصــف وطلــب ميــن املدعيــة علــى نفــي مادفــع بــه ‪-‬‬\n‫حلفــت املدعيــة اليمــن علــى أن املدعــى عليــه لــم ينفــق ســوى مبلــغ ألفــي‬\n‫ريــال منــذ اخللــع بتاريــخ ‪1429/7/10‬ه ـ ‪ -‬صــدر احلكــم علــى املدعــى‬\n‫عليــه بــأن يســلم للمدعيــة نفقــة ابنتــه املاضيــة وقدرهــا ثالثــة وأربعــون‬\n‫ألف ـ ًا وســتة وســتون ريــا ًال وســت هلــات وأن يلتــزم بســداد نفقــة شــهرية‬\n‫ال قدرهــا ألــف وســتمائة ريــال وهــذا احلكــم مشــمول بالنفــاذ‬     ‫مســتقب ً‬\n‫املعجــل وفــق املــادة (‪/199‬ب) مــن نظــام املرافعــات الشــرعية ‪ -‬قنعــت‬\n‫املدعيــة باحلكــم واعتــرض املدعــى عليهــا بالئحــة ‪ -‬صــدق احلكــم مــن‬\n                                                        ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪.........‬القاضــي يف احملكمــة العامــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بالريــاض املســاعد برقــم ‪ 33634070‬وتاريــخ ‪1433/11/01‬ه ـ‬\n‫املقيــدة برقــم ‪ 331818331‬وتاريــخ ‪1433/10/16‬ه ـ ففــي يــوم اإلثنــن‬\n‫املوافق‪1433/11/22‬ه ـ حضــرت ‪.........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي ‪.........‬واملعــرف بهــا مــن قبــل املدعــي ‪.........‬ســعودي‬\n‫بالســجل املدنــي رقــم ‪.........‬وادعــت املدعيــة قائلــة يف حتريــر دعواهــا إن‬\n‫املدعــى عليــه كان زوجــا لــي وقــد طلقنــي وقــد أجنبــت منــه ابنــه تدعــى‬\n‫‪ ...‬وعمرهــا خمســة أعــوام وهــي حتــت حضانتــي وال زالــت صغيــرة لــم‬\n                                                                                      ‫‪198‬‬\n\f      ‫ينفــق عليهــا منــذ والدتهــا وأنــا التــي أنفــق عليهــا حتــى تاريــخ هــذه اجللســة‬\n      ‫وقــد حتملــت أعبــاء ماليــة بســبب إنفاقــي عليهــا لــذا أطلــب احلكــم‬\n      ‫بإلــزام املدعــى عليــه بدفــع النفقــة املاضيــة واملســتقبلية هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه أجــاب بقولــه مــا ذكرتــه املدعيــة يف دعواهــا مــن‬\n      ‫اننــي كنــت زوجــا لهــا وأجنبــت لــي علــى فــراش الزوجيــة بنتــا تدعــى‬\n      ‫‪ ...‬ثــم طلقتهــا فهــذا صحيــح أمــا النفقــة فقــد انفقــت عليهــا مــدة ســنة‬\n      ‫ونصــف ثــم انقطعــت عــن النفقــة لكــون املدعيــة لــم تســمح لــي يف رؤيــة‬\n      ‫البنــت اال ثوانــي كمــا انــي اهــان اذا حضــرت للزيــارة هكــذا اجــاب‬\n      ‫ثــم جــرى ســؤال املدعــى عليــه عــن دخلــه الشــهري فأجــاب بقولــه راتبــي‬\n      ‫عشــرة آالف ومائتــن وخمســة وســبعني ريــال وحيــث األمــر مــا ذكــر‬\n      ‫قــررت الكتابــة إلــى هيئــة النظــر لتحديــد النفقــة حســب العــرف والعــادة‬\n      ‫وعليــه رفعــت اجللســة ويف يــوم الســبت املوافــق ‪1434/3/21‬ه ـ لــدي أنــا‬\n      ‫‪.........‬املــازم القضائــي املكلــف بعمــل املكتــب القضائــي الثامــن‬\n      ‫مبوجــب خطــاب فضيلــة رئيــس احملكمــة املســاعد لنــا القيــام بأعمــال‬\n      ‫مكتــب فضيلــة الشــيخ ‪.........‬برقــم ‪ 34697008‬يف ‪1434/3/21‬ه ـ‬\n      ‫حضــرت املدعيــة واملعــرف بهــا مــن قبــل املدعــى عليــه احلاضــر وبعــرض‬\n      ‫ماســبق ضبطــه عليهمــا صادقــا عليــه وقــد وردنــا قــرار مكتــب الصلــح‬\n      ‫باحملكمــة برقــم ‪ 82‬يف ‪1434/1/12‬ه ـ ونــص املقصــود منــه ( وملا تقدم‬\n      ‫فإننــا قدرنــا للبنــت ‪.........‬النفقــة املاضيــة ثمامنائــة ريــال واملســتقبلية ألــف‬\n      ‫وســتمائة ريــال هــذا مــا لدينــا واهلل يحفظكــم أعضــاء مكتــب الصلــح‬\n      ‫‪.........‬توقيعــه و‪.........‬توقيعــه )أ‪.‬ه ـ وبعــرض ذلــك علــى أطــراف الدعــوى‬\n      ‫قنعــت بــه املدعيــة واعتــرض عليــه املدعــى عليــه وبســؤال املدعيــة منــذ‬\n      ‫متــى كانــت تنفــق علــى ابنتهــا أجابــت بقولهــا إننــي كنــت أنفــق عليهــا‬\n\n\n‫‪199‬‬\n\f‫مــن تاريــخ مخالعتــي ‪1429/7/10‬ه ـ وبســؤال املدعــى عليــه هــل لديــه‬\n‫بينــة علــى أنــه كان ينفــق علــى ابنتــه مــدة ســنة ونصــف فأجــاب بقولــه‬\n‫البينــة لــدي هكــذا قــرر فجــرى إفهامــه بــأن لــه ميــن املدعيــة علــى نفــي‬\n‫ماجــاء يف دفعــه فقــال أطلــب ميينهــا علــى نفــي ذلــك هكــذا قــرر وبعــرض‬\n‫ذلــك علــى املدعيــة اســتعدت بــأداء اليمــن وبعــد تخويفهــا بــاهلل حلفــت‬\n‫قائلــة ( واهلل العظيــم إن املدعــى عليــه لــم ينفــق علــى ابنتــه ‪.........‬ســوى‬\n‫مبلــغ ألفــن ريــال منــذ خلعــت منــه بتاريــخ ‪1429/7/10‬ه ـ حتــى اآلن وأنــا‬\n‫التــي كنــت أنفــق عليهــا واهلل العظيــم) هكــذا حلفــت وبإجراء احلســاب‬\n‫مــن تاريــخ اخللــع ظهــر أن النفقــة املاضيــة املســتحقة للبنــت ‪.........‬قدرهــا‬\n‫خمســة وأربعــون ألف ـ ًا وســتة وســتون ريــا ًال وســت هلــات وبعــد خصــم‬\n‫األلفــن ريــال يصبــح مجمــوع املبلــغ ثالثــة وأربعــون ألف ـ ًا وســتة وســتون‬\n‫ـاء علــى ماتقــدم مــن الدعــوى واإلجابــة وملــا جــاء‬‫ريــا ًال وســت هلــات فبنـ ً‬\n‫يف قــرار مكتــب الصلــح املذكــور أعــاه فقــد حكمــت علــى املدعــى‬\n‫عليــه أن يســلم للمدعيــة نفقــة ابنتــه املاضيــة وقدرهــا ثالثــة وأربعــون‬\n‫ألف ـ ًا وســتة وســتون ريــا ًال وســت هلــات وأن يلتــزم بســداد نفقــة شــهرية‬\n‫ال قدرهــا ألــف وســتمائة ريــال وبــه حكمــت واهلل أعلــم وأحكــم‬      ‫مســتقب ً‬\n‫وهــذا احلكــم مشــمول بالنفــاذ املعجــل وفــق املــادة (‪/199‬ب) مــن نظــام‬\n‫املرافعــات الشــرعية وبعــرض احلكــم علــى الطرفــن قــررت املدعيــة‬\n‫قناعتهــا باحلكــم وقــرر املدعــى عليــه عــدم القناعــة وطلــب متكينــه مــن‬\n‫االســتئناف بالئحــة اعتراضيــة فأجيــب لطلبــه وجــرى تســليمه صــورة‬\n‫لنســخة احلكــم حــا ًال وأفهــم بــأن عليــه تقــدمي اعتراضــه خــال ثالثــن‬\n‫يومـ ًا وإذا مضــت املــدة احملــددة لالعتــراض ولــم يقــدم شــيئ ًا ســقط حقــه‬\n‫ـاء علــى املــادة ‪ 178‬مــن‬ ‫يف االعتــراض واكتســب احلكــم القطعيــة بنـ ً‬\n\n                                                                                        ‫‪200‬‬\n\f      ‫نظــام املرافعــات الشــرعية وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف‬\n                                                                         ‫‪1434/3/21‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ويف يــوم األحــد املوافــق ‪1434/7/2‬ه ـ وقــد عادت‬\n      ‫املعاملــة مــن محكمــة االســتئناف بخطــاب فضيلــة رئيــس محكمــة‬\n      ‫االســتئناف رقــم ‪ 3411168668‬يف ‪1434/5/27‬ه ـ وبرفقــه قــرار‬\n      ‫دائــرة األحــوال الشــخصية الثانيــة رقــم ‪ 34214757‬يف ‪1434/5/18‬ه ـ‬\n      ‫املتضمــن مــا نصــه (وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة لوحــظ أن قــدر مــا حكــم بــه مــن النفقــة‬\n      ‫املســتقبلية محــل نظــر وقــد ذكــر املدعــى عليــه يف الئحتــه االعتراضيــة‬\n      ‫دخلــه والتزامــات ماليــة عليــه ممــا يســتدعي إعــادة النظــر فيمــا قــدر‬\n      ‫وحكــم بــه وحتديــد النفقــة باملعــروف وعلــى ســعة املنفــق اقتضــاء لقولــه‬\n      ‫تعالــى (لينفــق ذو ســعة مــن ســعته ومــن قــدر عليــه رزقــه فلينفــق ممــا آتــاه‬\n      ‫اهلل ال يكلــف اهلل نفســا إال مــا آتاهــا ســيجعل اهلل بعــد عســر يســرا)‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n      ‫قاضــي اســتئناف ‪.........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.........‬ختمــه‬\n      ‫وتوقيعــه رئيــس الدائــرة ‪.........‬ختمــه وتوقيعــه) ولوجاهــة مــا ذكــره‬\n      ‫أصحــاب الفضيلــة قضــاة االســتئناف وفقهــم اهلل فقــد جــرى فتــح اجللســة‬\n      ‫هــذا اليــوم بحضــور أطــراف الدعــوى وبســؤال املدعــى عليــه عمــا جــاء يف‬\n      ‫قــرار هيئــة النظــر أجــاب بقولــه الــدكان الــذي بحــي ‪.........‬ال أملكــه‬\n      ‫ا ولكننــي شــريك فيــه بالنصــف واألرض الواقعــة غــرب املطــار‬            ‫كام ـ ً‬\n      ‫ا حتــى اآلن حيــث إنهــا أرض فضــاء غيــر‬         ‫عائــدة لــي وهــي التــدر دخ ـ ً‬\n      ‫مســتأجرة وأمــا بقيــة العقــارات املذكــورة يف قــرار هيئــة النظــر فغيــر‬\n      ‫صحيــح أننــي أملكهــا وال أعــرف عنهــا شــيئ ًا هكــذا قــرر وقــد جــرى‬\n\n\n‫‪201‬‬\n\f‫االطــاع علــى أوراق املعاملــة ووجــدت بهــا صــورة ضبــط مصدقــة للقطعة‬\n‫رقــم ‪ 1432‬بحــي ‪.........‬مســاحتها خمســمائة متــر مربــع واملذكــور يف‬\n‫الضبــط انتقــال كامــل العقــار ‪ .........‬كمــا وجــدت باملعاملــة كشــف‬\n‫حســاب جــاري مــن تاريــخ ‪2012/8/1‬م إلــى ‪2012/12/8‬م ووجــدت‬\n‫بهــا إيداعــات شــهرية تفــوق الثالثــن ألــف ريــال وبســؤال املدعــى عليــه‬\n‫عــن ذلــك قــرر بقولــه إن مــازاد عــن الراتــب التقاعــدي هــو عبــارة عــن‬\n‫قــروض اقترضتهــا هكــذا قــرر وبســؤال املدعــى عليــه عمــن يعولهــم‬\n‫أجــاب بقولــه إننــي أعــول ابنتــي ‪ ...‬وعمرهــا خمســة وعشــرون ســنة كمــا‬\n‫أننــي أعــول زوجتــن وأمــا الزوجــة الثالثــة فطلقتهــا يف شــهر شــوال‬\n‫مــن العــام املاضــي ‪1433‬ه ـ هكــذا قــرر وحيــث األمــر مــا ذكــر وملــا‬\n‫جــاء يف مناقشــة املدعــى عليــه وألن املدعــى عليــه أقــر بتملكــه لبعــض‬\n‫العقــارات وملــا جــاء يف املــادة ‪ 80‬مــن نظــام القضــاء واملادتــن ‪ 138‬و‪146‬‬\n‫مــن نظــام املرافعــات الشــرعية واملــادة كمــا أن املدعــى عليــه أقــر‬\n‫بدخــول أكثــر مــن ثالثــن ألــف ريــال شــهريا يف حســابه كمــا أنــه يعــول‬\n‫زوجتــن ال ثــاث كمــا ذكــر يف الئحتــه االعتراضيــة ونظــرا ألن مــا‬\n‫قــدره مكتــب الصلــح باحملكمــة يعــد أقــل مــا يجــب علــى مــن هــو يف‬\n‫مثــل حــال املدعــى عليــه فيمــا ظهــر لــي لذلــك كلــه فأنــا ال زلــت علــى‬\n‫مــا حكمــت بــه وأمــرت بإحلــاق ذلــك يف الصــك وســجله ورفــع املعاملــة‬\n‫حملكمــة االســتئناف لتدقيــق احلكــم وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                 ‫نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434/7/2‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n\n\n                                                                                      ‫‪202‬‬\n\f      ‫بالريــاض برقــم ‪ 341118668‬وتاريــخ ‪1434/8/22‬ه ـ املرفــق بها الصك‬\n      ‫الصــادر املســجل برقــم ‪ 34167121‬وتاريــخ ‪1434/3/21‬ه ـ اخلــاص‬\n      ‫بدعــوى‪......... /‬ســجل مدنــي رقــم ‪.........‬ضــد ‪ ......... /‬ســجل مدنــي‬\n      ‫رقــم ‪ .........‬قضيــة نفقــة أوالد وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه‪ .‬وحيــث ســبق دراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة وأوراق املعاملــة وباإلطــاع علــى مــا أجــاب بــه‬\n      ‫فضيلــة القاضــي وأحلقــه بالصــك بنــاء علــى قرارنــا رقــم ‪34214757‬‬\n      ‫وتاريــخ ‪1434/5/18‬ه ـ تقــرر الدائــرة بأنــه لــم يظهــر مــا يوجــب النقــض‬\n      ‫مــع تنبيــه فضيلتــه إلــى أنــه كان عليــه اإلشــارة يف بدايــة ضبــط القضيــة‬\n      ‫إلــى احلكــم املنقــوض الصــادر مــن فضيلــة القاضــي‪......... /‬يف القضيــة‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪203‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":197,"source_page_end":203,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"05786022dfd3a716711ce53c7cee61ec7a89314230e641b2ab28ae4557667838","normalized_text_hash":"d201a43299216d42b94c4ac0258437edf7c15c027cdf70ddca90cdb62fc2adfb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p197-34167121"},{"id":"ca3a8e52-c2da-5322-a1cb-48ee1fb69951","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -نفقة أوالد -طلب تقدير النفقة عن طريق قسم اخلبراء -تعلق الدعوى بحق واجب وضروري ودفعا للضرر -احلكم بنفقة شهرية لأوالد قبل تقديرها من قسم اخلبراء وشموله بالنفاذ","document_number":"34172149","case_number":"33645173","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/3/25","year":"1434","subject":"نفقة -نفقة أوالد -طلب تقدير النفقة عن طريق قسم اخلبراء -تعلق الدعوى بحق واجب وضروري ودفعا للضرر -احلكم بنفقة شهرية لأوالد قبل تقديرها من قسم اخلبراء وشموله بالنفاذ","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1432/3/25 :‬هـ‬\n                 ‫ُ‬                 ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪34172149 :‬‬\n                    ‫َر ْق ُم الدعوى‪33645173 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n            ‫‪ 34225436‬تاريخه‪1434/5/28 :‬هـ‬\n\n\n\n‫نفقــة ‪ -‬نفقــة أوالد ‪ -‬طلــب تقديــر النفقــة عــن طريــق قســم اخلبــراء‬\n‫‪ -‬تعلــق الدعــوى بحــق واجــب وضــروري ودفعــا للضــرر‪ -‬احلكــم بنفقــة‬\n‫شــهرية لــأوالد قبــل تقديرهــا مــن قســم اخلبــراء وشــموله بالنفــاذ‬\n                                                               ‫املعجــل ‪.‬‬\n\n\n\n\n             ‫‪ .1‬املادة ‪ 233‬من نظام املرافعات الشرعية والئحتها التنفيذية‬\n                                ‫‪ .2‬املادة ‪ 199‬من نظام املرافعات الشرعية‬\n\n\n\n\n‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه كان زوجهــا وطلقهــا ورزقــت منــه‬\n‫بابــن وبنــت وهمــا معهــا واملدعــى عليــه ال ينفــق عليهمــا وطالبــت بتحديــد‬\n‫نفقــة لهمــا ‪ -‬أجــاب املدعــى عليــه بــأن املدعيــة قامــت بأخــذ أوالدهــا‬\n‫وأنــه مســتعد بالنفقــة متــى مــا رجعــوا إلــى املنــزل الــذي يســكنون فيــه‬\n‫‪ -‬متــت الكتابــة لهيئــة النظــر لتقديــر النفقــة نظــر ًا ألن التقديــر يعتمــد‬\n‫علــى الدخــل الشــهري للمدعــى عليــه وحيــث إن االطــاع علــى الدخــل‬\n‫الشــهري يحتــاج إلــى مكاتبــات للجهــات املختصــة ولذلــك فقــد قــرر‬\n‫ناظــر القضيــة اســتناد ًا إلــى املــادة ‪ 233‬مــن نظــام املرافعــات الشــرعية‬\n‫والئحتهــا التنفيذيــة ونظــر ًا لتعلــق الدعــوى بحــق واجــب وضــروري ال‬\n                                                                                     ‫‪204‬‬\n\f      ‫يحتمــل التأخيــر ودفع ـ ًا للضــرر فقــد صــدر احلكــم علــى املدعــى عليــه‬\n      ‫بنفقــة شــهرية للولديــن قدرهــا ألــف ريــال وهــذا احلكــم خاضــع للتمييــز‬\n      ‫ومشــمول بالنفــاذ املعجــل اســتناد ًا للمــادة ‪ 199‬مــن نظــام املرافعــات‬\n      ‫الشــرعية ‪ -‬كمــا قــرر ناظــر القضيــة أنــه ســيتم حتديــد موعــد بعــد‬\n      ‫ورود واكتمــال اإلجابــات بخصــوص إثبــات الدخــل الشــهري للمدعــى‬\n            ‫عليــه ‪ -‬صــدر قــرار محكمــة االســتئناف باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ ).....‬القاضــي يف احملكمــة العامــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بالرياض‪/‬املســاعد برقــم ‪ 33645173‬وتاريــخ ‪ 1433/11/09‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331980719‬وتاريــخ ‪ 1433/11/09‬ه ـ ففــي‬\n      ‫يــوم الســبت املوافــق‪ 1434/01/10‬ه ـ افتتحــت اجللســة األولــى الســاعة‬\n      ‫‪ 08 : 15‬وفيهــا حضــرت (‪ ).....‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم (‪ ).....‬واملعــرف بهــا مــن قبــل أبنهــا (‪ ).....‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم(‪ ).....‬وادعــت علــى احلاضــر معهــا (‪).....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬قائلــة إن املدعــى‬\n      ‫عليــه زوجــي ســابق ًا وقــد طلقنــي مبوجــب صــك الطــاق الصــادر مــن‬\n      ‫محكمة األحوال الشــخصية رقم ‪ 8/22/93‬يف ‪ 1433/9/11‬هـ واآلن‬\n      ‫أوالدي منــه املولــود يف ‪1421/02/28‬ه ـ و املولــودة يف ‪ 1424/05/10‬ه ـ‬\n      ‫معــي وال ينفــق عليهــم أطلــب حتديــد نفقــة لهمــا هــذه دعــواي وبعــرض‬\n      ‫الدعــوى علــى املدعــى عليــه قــال إن املدعيــة قامــت بأخــذ أوالدي جميعـ ًا‬\n      ‫بتاريــخ ‪1433/11/25‬ه ـ وأنــا مســتعد بالنفقــة عليهــم متــى رجعــو‬\n‫‪205‬‬\n\f‫إلــى منزلــي الــذي يســكنون فيــه هكــذا أجــاب وبعــرض ذلــك علــى‬\n‫املدعيــة قالــت هــم مــن أتــوا إلــي حيــث أنهــم ذهبــوا ملنــزل و الدهــم يف‬\n‫شــهر شــوال مــن هــذا العــام مــن أجــل الدراســة ورجعــوا لــي بعــد اســبوع‬\n‫تقريب ـ ًا بســبب عــدم النفقــة عليهــم وعــدم وجــود طعــام يف املنــزل و أنــا‬\n‫أطالــب بنفقتهــم مــن التاريــخ الــذي يدعــي املدعــى عليــه أنهــم بقــو معــه‬\n‫ـاء علــى خطابنــا‬‫وهــو ‪ 1433/11/25‬ه ـ هكــذا ذكــرت بعــد ذلــك وبنـ ً‬\n‫املوجــه لهيئــة النظــر بعــد ورود املعاملــة لتقديــر نفقــة للولديــن للحكــم‬\n‫ال حيــث وردنــا خطــاب هيئــة النظــر املتضمــن طلــب‬   ‫بهــا حكمـ ًا مســتعج ً‬\n‫حتديــد الدخــل الشــهري للمدعــى عليــه وعليــه جــرى ســؤال املدعــى عليه‬\n‫عــن دخلــه فقــال ليــس لــدي ســوى بقالــة و ثــاث عمائــر صغيــرة دخلهــا‬\n‫بســيط هكــذا ذكــر وبعــرض ذلــك علــى املدعيــة قالــت مــا ذكــره غير‬\n‫صحيــح و الصحيــح أن للمدعــى عليــه عمارتــن يف شــارع ‪ ...‬ويف شــارع ‪...‬‬\n‫وعمــارة عنــد مســجد ‪ ...‬ويف الدخــل احملــدود ‪ ...‬وخمــس عمايــر يف ‪ ...‬و‬\n‫غيرهــا ال أعلمــه هكــذا ذكــرت وبعــرض ذلــك علــى املدعــى عليــه قــال‬\n‫الصحيــح مــا ذكرتــه بعــد ذلــك اقتضــى النظــر الكتابــة لهيئــة النظــر‬\n‫للشــخوص للعمايــر التــي تدعــي املدعيــة أنهــا ملــك للمدعــى عليــه كمــا‬\n‫ســيتم الكتابــة ملؤسســة النقــد لإلفــادة عــن ارصــدة املدعى عليه وســيتم‬\n‫حتديــد موعــد بعــد ورود اإلفــادات ونظــرا لتعلــق الدعــوى بحــق واجــب‬\n‫وضــروري ال يحتمــل التأخيــر ودفعــا للضــرر واســتنادا علــى املــادة ‪233‬‬\n‫مــن نظــام املرافعــات الشــرعية والئحتهــا التنفيذيــة فقــد حكمــت علــى‬\n‫املدعــى عليــه بنفقــة شــهرية لولديــه قدرهــا ألــف ريــال وهــذا احلكــم‬\n‫خاضــع للتمييــز ومشــمول بالنفــاذ املعجــل اســتنادا علــى املــادة ‪ 233‬مــن‬\n‫نظــام املرافعــات الشــرعية والئحتهــا التنفيذيــة واملــادة ‪ 199‬مــن نظــام‬\n\n\n                                                                                    ‫‪206‬‬\n\f      ‫املرافعــات الشــرعية وبعــرض احلكــم علــى الطرفــن قنعــا بــه ومت إقفــال‬\n      ‫اجللســة الســاعة ‪ 08،45‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                           ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/01/10‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة املختصــة‬\n      ‫بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف‬\n      ‫بالريــاض علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض املســاعد برقــم ‪ 331980719‬وتاريــخ ‪1433/5/7‬هـ املرفق بها‬\n      ‫الصــك الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ........ /‬املســجل‬\n      ‫برقــم ‪ 34172149‬وتاريــخ ‪1434/3/25‬ه ـ اخلــاص بدعــوى‪ ).....(/‬ضــد‬\n      ‫‪ ).....(/‬يف قضيــة نفقــة أوالد وقــد تضمــن الصــك حكــم فضيلتــه مبــا‬\n      ‫هــو مــدون ومفصــل فيــه‪ .‬وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n      ‫االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة باألكثريــة املصادقــة علــى‬\n      ‫احلكــم‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                                                ‫وســلم ‪.‬‬\n\n\n\n\n‫‪207‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":204,"source_page_end":207,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"160e87d862855670714ff866e249f06f2ad5d7cdbca126217381cee6e96b3c45","normalized_text_hash":"a979814279f5c0fd21c8d61123444f6f984c2bdb4ea19fa5a47ddfc9d82eeaeb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p204-34172149"},{"id":"69d5a04c-8161-5df4-bee1-14c7da5fa52a","document_type":"judgment","category":"judicial","subcategory":"general","title":"نفقة -مطالبة أم بنفقة أوالدها السابقة واملستقبلية -مطالبة أم بقيمة عملية والدة لدى مستشفى خاص -إمضاء صلح ورجع عنه املدعى عليه -خيار املجلس يف الصلح -احلكم بالنفقة على","document_number":"33462627","case_number":"33647365","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/12/22","year":"1434","subject":"نفقة -مطالبة أم بنفقة أوالدها السابقة واملستقبلية -مطالبة أم بقيمة عملية والدة لدى مستشفى خاص -إمضاء صلح ورجع عنه املدعى عليه -خيار املجلس يف الصلح -احلكم بالنفقة على","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1433/12/22 :‬هـ‬\n                  ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪33462627 :‬‬\n                    ‫َر ْق ُم الدعوى‪33647365 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n             ‫‪ 3463335‬تاريخه‪1434/3/16 :‬هـ‬\n\n\n\n ‫نفقــة ‪ -‬مطالبــة أم بنفقــة أوالدهــا الســابقة واملســتقبلية ‪ -‬مطالبــة‬\n ‫أم بقيمــة عمليــة والدة لــدى مستشــفى خــاص ‪ -‬إمضــاء صلــح ورجــع‬\n ‫عنــه املدعــى عليــه ‪ -‬خيــار املجلــس يف الصلــح ‪ -‬احلكــم بالنفقــة علــى‬\n                                                             ‫املدعــى عليــه‪.‬‬\n\n\n\n\n ‫قــال يف كشــاف القنــاع ‪ ( 200/3‬خيــار املجلــس مــا لم يتفرقــا بأبدانهما‬\n          ‫ومت العقــد وتفرقــا مــن مجلســه لــم يكــن لواحد منهم الفســخ )‬\n\n\n\n\n ‫ادعــت املدعيــة ضــد املدعــى عليــه أنــه كان زوجهــا ورزقــت منــه بابنــن‬\n ‫وهــو مســجون يف قضيــة أخالقيــة وحكــم عليــه بأربــع ســنوات وهــو لــم‬\n ‫ينفــق علــى املدعيــة وال علــى ابنيهــا مــن ‪1433/10/18‬ه ـ وقــد أجريــت‬\n ‫لهــا عمليــة والدة بعشــرة آالف دفــع منهــا املدعــى عليــه ثالثــة آالف وبقــي‬\n ‫ســبعة آالف وطالبــت املدعيــة بنفقــة ابنيهــا مــن ‪1433/10/18‬ه ـ وأن‬\n ‫يســلم باقــي قيمــة العمليــة ‪ -‬ونفقــة شــهر لهــا ‪ -‬أجــاب املدعــى عليــه‬\n ‫باملصادقــة علــى الدعــوى وال مانــع لديــه مــن تســليم النفقــة وقيمــة‬\n ‫ـاء‬\n ‫العمليــة ‪ -‬أصلــح ناظــر القضيــة بــن الطرفــن ثــم صــدر احلكــم بنـ ً‬\n ‫علــى الصلــح أن يســلم املدعــى عليــه للمدعيــة مبلــغ ســبعة آالف ريــال‬\n                                                                                     ‫‪208‬‬\n\f      ‫باقــي قيمــة العمليــة وأن يســلم لهــا ســبعمائة ريــال نفقــة لهــا عــن الشــهر‬\n      ‫املاضــي وأن يســلم للمدعيــة كل شــهر ألــف وأربعمائة ريــال نفقة البنيها‬\n      ‫اعتبــار ًا مــن ‪1433/10/18‬ه ـ ويســتمر يف ذلــك شــهري ًا ‪ -‬قنــع الطرفــان‬\n      ‫باحلكــم ‪ -‬رجــع املدعــى عليــه عــن الصلــح وقــرر عــدم القناعــة ‪ -‬النتهــاء‬\n      ‫خيــار املجلــس قــررت احملكمــة اســتمرار حكــم الصلــح ‪-‬صــدر قــرار‬\n      ‫محكمــة االســتئناف مبنطقــة املدينــة املنــورة بالقــرار رقــم ‪ 3463335‬يف‬\n                                          ‫‪1434/3/16‬ه ـ باملوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .......‬القاضــي يف احملكمــة‬\n      ‫العامــة باملدينــة املنــورة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 33647365‬وتاريــخ‬\n      ‫‪1433/11/10‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331991063‬وتاريــخ‬\n      ‫‪1433/11/10‬ه ـ ففــي يــوم االثنــن املوافــق ‪1433/11/22‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10:30‬وفيهــا حضــرت املدعيــة‪ ....... /‬ســعودية بالســجل‬\n      ‫املدنــي رقــم ‪ .......‬وادعــت علــى احلاضــر معهــا يف مجلــس احلكــم ‪.......‬‬\n      ‫ســعودي بالســجل املدنــي رقــم ‪ .......‬قائل ـ ًة يف دعواهــا إن هــذا احلاضــر‬\n      ‫معــي هــو زوجــي تزوجنــي قبــل ثــاث ســنوات وأجنبــت منــه ابنــن‬\n      ‫وهمــا‪...‬و‪ ...‬عمــره ســنتان و‪ .........‬عمــره ثالثــة أســابيع وقــد قبــض عليــه‬\n      ‫يف قضيــة أخالقيــة واآلن هــو مســجون فيهــا وحكــم عليــه يف احلــق العــام‬\n      ‫أربــع ســنوات وســتمائة جلــدة ولــم ينفــق علــي وال علــى ابنــي االثنــن منــذ‬\n      ‫‪1433/10/18‬ه ـ وقــد فســخ نكاحــي منــه اليــوم وقــد أجريــت عمليــة‬\n      ‫والدة بعشــرة آالف ريــال دفــع والــده منهــا ثالثــة آالف ريــال أطلــب احلكم‬\n‫‪209‬‬\n\f‫ولدي من ‪1433/10/18‬هـ‬        ‫َ‬        ‫عليه بأن يدفع لي نفقة شــهر وأن ينفق على‬\n‫وأن يدفــع لــي بقيــة قيمــة العمليــة وقــدره ســبعة آالف ريــال‪ ،‬وبســؤال‬\n‫املدعــى عليــه أجــاب بقولــه مــا ذكرتــه املدعيــة صحيــح وال مانــع لــدي‬\n‫مــن النفقــة ومــن دفــع بقيــة قيمــة العمليــة هكــذا أجــاب ثــم أصلحــت‬\n‫بــن الطرفــن علــى أن تكــون النفقــة للزوجــة واالبنــن يف كل شــهر‬\n‫ســبعمائة ريــال فرضــي بذلــك الطرفــان فبنــاء علــى مــا تقــدم وملــا ســبق‬\n‫مــن الدعــوى واإلجابــة وملــا جــاء يف الصلــح املذكــور فقــد حكمــت مبــا‬\n‫يلــي‪ :‬أوال‪ :‬يدفــع املدعــى عليــه للمدعيــة ســبعة آالف ريــال قيمــة املتبقــي‬\n‫مــن العمليــة‪ .‬ثانيـاً‪ :‬يدفــع املدعــى عليــه للمدعيــة ســبعمائة ريــال نفقــة لهــا‬\n‫عــن الشــهر املاضــي‪ .‬ثالثـاً‪ :‬يدفــع املدعــى عليــه للمدعيــة كل شــهر ألــف‬\n‫وأربعمائــة ريــال نفقــة البنيهــا اعتبــار ًا مــن ‪1433/10/18‬ه ـ ويســتمر يف‬\n‫ذلــك شــهرياً‪ .‬وبعــرض ذلــك علــى الطرفــن قنعــا بــه ثــم عــاد املدعــى عليــه‬\n‫قبــل التوقيــع وقــرر عــدم قناعتــه باحلكــم وحيــث إن خيــار املجلــس قــد‬\n‫انتهــى فقــد اتفقــا لــدي يف املجلــس الشــرعي ثــم خرجــا وعنــد املوظــف‬\n‫يف مكتبــه رجــع املدعــى عليــه عــن الصلــح وحيــث إن خيــار املجلــس قــد‬\n‫انتهــى بخروجهمــا مــن املجلــس الشــرعي فالصلــح ملــزم للطرفــن قــال‬\n‫يف كشــاف القنــاع ‪( : 200/3‬خيــار املجلــس مــا لــم يتفرقــا بأبدانهمــا‬\n‫ومتــى مت العقــد وتفرقــا مــن مجلســه لــم يكــن لواحــد منهمــا الفســخ)‪.‬‬\n‫وأفهمتــه بــأن عليــه مراجعــة احملكمــة خــال عشــرة أيــام الســتالم‬\n‫صــورة مــن صــك احلكــم لتقــدمي الالئحــة االعتراضيــة خــال ثالثــن‬\n‫يوم ـ ًا مــن تاريــخ اســتالمه وإذا تأخــر عــن املــدة النظاميــة فــإن حقــه مــن‬\n‫االســتئناف يســقط وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                             ‫وســلم‪ .‬حــرر يف ‪1433/11/22‬ه ـ‬\n\n\n                                                                                          ‫‪210‬‬\n\f      ‫ويف يــوم الســبت املوافــق ‪1434/4/6‬ه ـ عــادت املعاملــة مــن محكمــة‬\n      ‫االســتئناف املقيــدة باحملكمــة برقــم ‪ 34/626216‬وتاريــخ‬\n      ‫‪1434/3/29‬ه ـ بخصــوص دعــوى املــرأة‪ ....... /‬ضــد‪ ....... /‬يف نفقة وقد‬\n      ‫ظهــر علــى الصــك مــن الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف مبكــة‬\n      ‫املكرمــة مــا نصــه‪ :‬فقــد اطلعنــا علــى هــذا الصــك رقــم ‪33462627‬‬\n      ‫وتاريــخ ‪1433/11/22‬ه ـ الصــادر مــن فضيلــة القاضــي‪ ....... /‬وأصدرنــا‬\n      ‫القــرار رقــم ‪ 3463335‬وتاريــخ ‪1434/3/16‬ه ـ املتضمــن املوافقــة علــى‬\n      ‫احلكــم‪ .‬قاضــي اســتئناف ‪ .......‬ختمــه وتوقيعــه‪ ،‬قاضــي اســتئناف ‪.......‬‬\n      ‫ختمــه وتوقيعــه‪ ،‬رئيــس الدائــرة ختمــه وتوقيعــه وصلــى اهلل علــى نبينــا‬\n                   ‫محمــد وعلــى آلــه وصحبــه وســلم‪ ،‬حــرر يف ‪1434/4/6‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية‬\n      ‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 34/326556‬وتاريــخ‬\n      ‫‪1434/ 3/4‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‪....... /‬‬\n      ‫القاضــي باحملكمــة العامــة باملدينــة املنــورة برقــم ‪ 33462627‬وتاريــخ‬\n      ‫‪1433/ 11/22‬ه ـ املتضمــن دعــوى املــرأة ‪ .........‬ضــد ‪.........‬يف نفقــة‪،‬‬\n      ‫وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة‬\n      ‫علــى احلكــم ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه‬\n                                                                    ‫وصحبــه وســلم ‪،‬‬\n\n\n\n‫‪211‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"57f09a6b-4a00-5729-88c5-b95e7784cb58","source_page_start":208,"source_page_end":211,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"832947b7b18b623974bbc24f17b24309fe0f07227a1232339d3c859bf47e7e26","normalized_text_hash":"ff4d952ee2bea1a16540d307630560d76afb032743a7003355d582f24d69e00e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v12-p208-33462627"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

